/** Embedded Disc Number capture through the real Content Manager and legacy upload controllers. */
import assert from 'node:assert/strict';
import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { after, before, beforeEach, test } from 'node:test';
import { ObjectId } from 'mongodb';

import { postAudioTrack } from '../../src/controllers/audioTrackController';
import { bulkUploadAudioTracksWeb, createAudioTrackWeb } from '../../src/controllers/contentManager/mediaController';
import { getDb } from '../../src/infrastructure/database';
import { getS3 } from '../../src/infrastructure/s3';
import { retryAudioTrackPublications } from '../../src/services/audio/audioPublicationRecoveryService';
import { startLocalS3 } from '../support/localS3';
import { startMongoReplicaSet, type MongoReplicaSetHarness } from '../support/mongoReplicaSet';
import { createPcmWav, withId3Positions } from '../support/pcmWav';

let mongo: MongoReplicaSetHarness;
let storage: Awaited<ReturnType<typeof startLocalS3>>;
let uploadDirectory: string;
const ownedEnvironment = ['AWS_ENDPOINT_URL_S3', 'AWS_REGION', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY', 'AWS_SESSION_TOKEN', 'S3_BUCKET_NAME', 'S3_MAX_ATTEMPTS'] as const;
const oldEnvironment = Object.fromEntries(ownedEnvironment.map(key => [key, process.env[key]]));

before(async () => {
    mongo = await startMongoReplicaSet('archtree-audio-disc-capture-test');
    storage = await startLocalS3();
    process.env.AWS_ENDPOINT_URL_S3 = storage.endpoint;
    process.env.AWS_REGION = 'us-east-1';
    process.env.AWS_ACCESS_KEY_ID = 'owned-local-fixture';
    process.env.AWS_SECRET_ACCESS_KEY = 'owned-local-fixture-secret';
    delete process.env.AWS_SESSION_TOKEN;
    process.env.S3_BUCKET_NAME = storage.bucket;
    process.env.S3_MAX_ATTEMPTS = '2';
    uploadDirectory = mkdtempSync(path.join(tmpdir(), 'archtree-disc-capture-'));
});
beforeEach(async () => {
    for (const collection of ['audioTracks', 'albums', 'artists', 'users', 'imageAssets']) {
        await getDb()!.collection(collection).deleteMany({});
    }
    storage.objects.clear(); storage.requests.length = 0;
    storage.controls.dropPutResponses = false;
});
after(async () => {
    getS3().destroy();
    await storage?.stop(); await mongo?.stop();
    if (uploadDirectory) rmSync(uploadDirectory, { recursive: true, force: true });
    for (const key of ownedEnvironment) {
        if (oldEnvironment[key] === undefined) delete process.env[key]; else process.env[key] = oldEnvironment[key];
    }
});

/**
 * Writes a tagged WAV to a `.wav` temporary path, as the disk upload middleware does, so the real
 * metadata reader selects its parser by extension.
 */
const taggedWav = (name: string, positions: { track?: string; disc?: string }): Express.Multer.File => {
    const bytes = withId3Positions(createPcmWav(400), positions);
    const filePath = path.join(uploadDirectory, `${new ObjectId().toHexString()}-${name}`);
    writeFileSync(filePath, bytes);
    return {
        fieldname: 'mediaFile', originalname: name, encoding: '7bit', mimetype: 'audio/wav',
        path: filePath, size: bytes.length
    } as Express.Multer.File;
};

/** Seeds one administrator and one ready Album, optionally with an existing disc 1 member. */
const seedAlbum = async (members: Array<Record<string, unknown>> = []) => {
    const owner = new ObjectId();
    const albumId = new ObjectId();
    await getDb()!.collection('users').insertOne({ _id: owner, role: 'admin', email: `${owner}@example.test` });
    await getDb()!.collection('albums').insertOne({
        _id: albumId, title: 'Disc Capture Album', audioTrackIds: members.map((member) => String(member._id)),
        lifecycleStatus: 'ready', referenceRevision: 0
    });
    if (members.length > 0) {
        await getDb()!.collection('audioTracks').insertMany(members.map((member) => ({
            title: 'Existing member', albumId: albumId.toHexString(), uploadStatus: 'ready',
            s3Key: String(member._id), publicationStatus: 'ready', ...member
        })));
    }
    return { owner: owner.toHexString(), albumId: albumId.toHexString() };
};

const createSingle = async (owner: string, albumId: string, file: Express.Multer.File, title: string) => {
    let redirect = '';
    await createAudioTrackWeb({
        body: { title, albumId, attributionUnknown: 'true' },
        auth: { userId: owner, role: 'admin' },
        files: { mediaFile: [file] }
    } as any, { redirect: (location: string) => { redirect = location; }, locals: {} } as any,
    (error?: unknown) => { throw error; });
    return decodeURIComponent(redirect);
};

const albumOrder = async (albumId: string) =>
    (await getDb()!.collection('albums').findOne({ _id: new ObjectId(albumId) }))!.audioTrackIds;

test('a single Content Manager upload stores its embedded Disc Number and orders the Album by disc', async () => {
    const existingId = new ObjectId();
    const { owner, albumId } = await seedAlbum([{ _id: existingId, trackNumber: 5 }]);

    const message = await createSingle(owner, albumId, taggedWav('disc-two.wav', { track: '3', disc: '2/2' }), 'Disc two track three');
    assert.match(message, /Audio MediaTrack created successfully/);
    const track = await getDb()!.collection('audioTracks').findOne({ title: 'Disc two track three' });
    assert.ok(track);
    assert.equal(track.discNumber, 2);
    assert.equal(track.discNumberSource, 'embedded');
    assert.equal(track.trackNumber, 3);
    // Track 3 on disc 2 follows Track 5 on (implicit) disc 1.
    assert.deepEqual(await albumOrder(albumId), [existingId.toHexString(), track._id.toHexString()]);
});

test('an untagged or out-of-range disc stores no Disc Number keys and the upload still succeeds', async () => {
    const { owner, albumId } = await seedAlbum();
    assert.match(await createSingle(owner, albumId, taggedWav('untagged.wav', {}), 'Untagged upload'), /created successfully/);
    assert.match(await createSingle(owner, albumId, taggedWav('disc-1000.wav', { track: '1', disc: '1000' }), 'Disc 1000 upload'), /created successfully/);
    for (const title of ['Untagged upload', 'Disc 1000 upload']) {
        const track = await getDb()!.collection('audioTracks').findOne({ title });
        assert.ok(track);
        assert.equal('discNumber' in track, false, title);
        assert.equal('discNumberSource' in track, false, title);
        assert.equal(track.publicationStatus, 'ready', title);
    }
});

test('bulk upload stores each file\'s Disc Number independently and orders the Album by disc then Track Number', async () => {
    const { owner, albumId } = await seedAlbum();
    const response: { statusCode?: number; body?: any } = {};
    await bulkUploadAudioTracksWeb({
        body: { albumId, attributionUnknown: 'true' },
        auth: { userId: owner, role: 'admin' },
        files: [
            taggedWav('a-disc-two.wav', { track: '1', disc: '2' }),
            taggedWav('b-no-disc.wav', { track: '2' }),
            taggedWav('c-disc-zero.wav', { track: '1', disc: '0' })
        ],
        get: (name: string) => name === 'X-Requested-With' ? 'XMLHttpRequest' : undefined
    } as any, {
        status(code: number) { response.statusCode = code; return this; },
        json(body: unknown) { response.body = body; return this; },
        redirect() { throw new Error('The XHR bulk path must answer with JSON.'); },
        locals: {}
    } as any, (error?: unknown) => { throw error; });

    assert.equal(response.statusCode, 200);
    assert.equal(response.body.publishedCount, 3);
    assert.deepEqual(response.body.outcomes.map((outcome: any) => [outcome.originalFileName, outcome.uploadStatus, outcome.publicationStatus]), [
        ['a-disc-two.wav', 'ready', 'ready'],
        ['b-no-disc.wav', 'ready', 'ready'],
        ['c-disc-zero.wav', 'ready', 'ready']
    ]);
    const byName = new Map((await getDb()!.collection('audioTracks').find({}).toArray())
        .map((track) => [track.originalFileName, track]));
    const a = byName.get('a-disc-two.wav')!, b = byName.get('b-no-disc.wav')!, c = byName.get('c-disc-zero.wav')!;
    assert.deepEqual([a.discNumber, a.discNumberSource, a.trackNumber], [2, 'embedded', 1]);
    for (const track of [b, c]) {
        assert.equal('discNumber' in track, false);
        assert.equal('discNumberSource' in track, false);
    }
    assert.deepEqual([b.trackNumber, c.trackNumber], [2, 1]);
    assert.deepEqual(await albumOrder(albumId), [c, b, a].map((track) => track._id.toHexString()));
});

test('the legacy JSON upload endpoint stores the embedded Disc Number', async () => {
    const { owner, albumId } = await seedAlbum();
    const artistId = new ObjectId();
    await getDb()!.collection('artists').insertOne({
        _id: artistId, name: 'Disc Capture Artist', albumIds: [], lifecycleStatus: 'ready', referenceRevision: 0
    });
    const response: { statusCode?: number; body?: any } = {};
    await postAudioTrack({
        body: { title: 'Legacy disc upload', artistIds: JSON.stringify([artistId.toHexString()]), albumId },
        auth: { userId: owner, role: 'admin' },
        files: { audioFile: [{ ...taggedWav('legacy.wav', { track: '4', disc: '2' }), fieldname: 'audioFile' }] }
    } as any, {
        status(code: number) { response.statusCode = code; return this; },
        json(body: unknown) { response.body = body; return this; },
        locals: {}
    } as any, (error?: unknown) => { throw error; });

    assert.equal(response.statusCode, 201);
    const track = await getDb()!.collection('audioTracks').findOne({ _id: new ObjectId(response.body.audioTrackId) });
    assert.deepEqual([track!.discNumber, track!.discNumberSource, track!.trackNumber], [2, 'embedded', 4]);
    assert.deepEqual(await albumOrder(albumId), [response.body.audioTrackId]);
});

test('a lost PUT keeps the Disc Number on the recorded upload, and publication retry orders by disc', async () => {
    const { owner, albumId } = await seedAlbum();
    storage.controls.dropPutResponses = true;
    const uncertain = await createSingle(owner, albumId, taggedWav('uncertain.wav', { track: '1', disc: '3' }), 'Uncertain disc upload');
    assert.match(uncertain, /upload outcome could not be confirmed/);
    const pending = await getDb()!.collection('audioTracks').findOne({ title: 'Uncertain disc upload' });
    assert.ok(pending);
    assert.equal(pending.pendingUploadOutcomeUnknown, true);
    assert.deepEqual([pending.discNumber, pending.discNumberSource], [3, 'embedded']);
    assert.deepEqual(await albumOrder(albumId), []);

    // Two stored uploads whose publication failed are retried in reverse disc order.
    storage.controls.dropPutResponses = false;
    await createSingle(owner, albumId, taggedWav('disc-two.wav', { track: '1', disc: '2' }), 'Retry disc two');
    await createSingle(owner, albumId, taggedWav('disc-one.wav', { track: '9', disc: '1' }), 'Retry disc one');
    const discTwo = (await getDb()!.collection('audioTracks').findOne({ title: 'Retry disc two' }))!;
    const discOne = (await getDb()!.collection('audioTracks').findOne({ title: 'Retry disc one' }))!;
    await getDb()!.collection('albums').updateOne({ _id: new ObjectId(albumId) }, { $set: { audioTrackIds: [] } });
    await getDb()!.collection('audioTracks').updateMany(
        { _id: { $in: [discTwo._id, discOne._id] } },
        { $set: { publicationStatus: 'failed', publicationError: 'Synthetic publication failure' } }
    );

    const retry = await retryAudioTrackPublications([discTwo._id.toHexString(), discOne._id.toHexString()]);
    assert.equal(retry.readyCount, 2);
    assert.deepEqual(await albumOrder(albumId), [discOne._id.toHexString(), discTwo._id.toHexString()]);
});
